// Faultline delivers at-least-once. Verify the HMAC, reject replays, dedupe by event_id.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;
const DEDUPE_SECONDS = 3600;

const item = $input.first();
const headers = item.json.headers || {};
const ts = String(headers['x-faultline-timestamp'] || '');
const signature = String(headers['x-faultline-signature'] || '');
const secret = $env.FAULTLINE_WEBHOOK_SECRET || '';
const now = Math.floor(Date.now() / 1000);
const reject = (reason) => [{ json: { status: 'rejected', http: 401, reason } }];

let raw;
try {
  raw = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (error) {
  raw = Buffer.from((item.binary && item.binary.data && item.binary.data.data) || '', 'base64');
}

if (!secret) return reject('FAULTLINE_WEBHOOK_SECRET is not set for n8n');
if (!/^\d+$/.test(ts) || Math.abs(now - Number(ts)) > MAX_SKEW_SECONDS) {
  return reject('missing or stale timestamp');
}
const expected = Buffer.from(
  'sha256=' +
    crypto.createHmac('sha256', secret).update(Buffer.concat([Buffer.from(ts + '.'), raw])).digest('hex'),
);
const given = Buffer.from(signature);
if (expected.length !== given.length || !crypto.timingSafeEqual(expected, given)) {
  return reject('bad signature');
}

const event = JSON.parse(raw.toString('utf8'));
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
for (const [id, at] of Object.entries(store.seen)) {
  if (now - at > DEDUPE_SECONDS) delete store.seen[id];
}
const duplicate = Object.prototype.hasOwnProperty.call(store.seen, event.event_id);
if (!duplicate) store.seen[event.event_id] = now;

return [{ json: { ...event, status: duplicate ? 'duplicate' : 'accepted', http: 200 } }];

// Only new, verified events reach people. Faultline stays the source of truth.
const pct = (x) => (100 * (x || 0)).toFixed(1) + '%';
const out = [];
for (const item of $input.all()) {
  const e = item.json;
  if (e.status !== 'accepted') continue;
  const m = e.metrics || {};
  let action = 'notify_channel';
  if (e.type === 'RESOLVED') action = 'close_incident';
  else if (e.severity === 'CRITICAL') action = 'page_on_call';
  else if (e.severity === 'HIGH') action = 'open_incident';
  const message =
    e.type === 'RESOLVED'
      ? `RESOLVED ${e.service}: error rate back to ${pct(m.error_rate_short)}`
      : `${e.severity} ${e.service}: error rate ${pct(m.error_rate_short)} vs baseline ` +
        `${pct(m.baseline)}, burn ${m.burn_short}x, z=${m.z}`;
  out.push({
    json: {
      action,
      message,
      event_id: e.event_id,
      alert_id: e.alert_id,
      type: e.type,
      service: e.service,
      severity: e.severity,
    },
  });
}
return out;
